sections.css:
.bcn-search-trigger .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-admin-btn .esa-icon {
  block-size: 14px;
  inline-size: 14px;
}
.bcn-gd__label .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-gd-row .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-disclosure .esa-icon {
  transition: transform 0.15s;
}
.bcn-disclosure[aria-expanded="false"] .esa-icon {
  transform: rotate(-90deg);
}
@media (prefers-reduced-motion: reduce) {
  .bcn-disclosure .esa-icon {
    transition: none;
  }
}
.bcn-ev-staging__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-ev-targets__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.user-panel__item .esa-icon {
  color: var(--bcn-gray-500);
}
.user-panel__item--danger .esa-icon {
  color: var(--color-background-utility-danger);
}
.project-switcher__trigger > .esa-icon:first-child {
  color: var(--bcn-gray-500);
  flex-shrink: 0;
}
.nav-section__header:hover .esa-icon,
.nav-section--active .nav-section__header,
.nav-section--active .nav-section__header .esa-icon {
  color: var(--color-background-brand);
}
.nav-section__header > .esa-icon:first-child {
  color: var(--bcn-gray-950);
  flex-shrink: 0;
  transition: color 0.15s;
}
.nav-section__header > .esa-icon:last-child {
  color: var(--bcn-gray-400);
  flex-shrink: 0;
  transition:
    transform 0.15s,
    opacity 0.2s ease-in-out;
}
.nav-section--collapsed .nav-section__header > .esa-icon:last-child {
  transform: rotate(-90deg);
}
.side-nav.collapsed .nav-section__title,
.side-nav.collapsed .nav-section__header > .esa-icon:last-child {
  display: none;
}
.bcn-mod__link .esa-icon {
  color: var(--bcn-content-muted);
}
.bcn-phome {
  background: var(--color-background-elevation-raised);
  border-bottom: 1px solid var(--color-border-default);
}
.bcn-phome__cover {
  background: var(--color-background-elevation-sunken);
  height: 132px;
  position: relative;
  overflow: hidden;
}
.bcn-phome__hero {
  object-fit: cover;
  width: 100%;
  height: 100%;
  display: block;
}
.bcn-phome__body {
  align-items: flex-start;
  gap: var(--spacing-500);
  padding: 0 var(--spacing-600) var(--spacing-500);
  display: flex;
}
@media (width<=640px) {
  .bcn-phome__body {
    gap: var(--spacing-400);
    flex-direction: column;
  }
}
.bcn-phome__edit {
  align-items: center;
  gap: var(--spacing-150);
  padding: var(--spacing-150) var(--spacing-250);
  font-family: inherit;
  font-size: 0.8125rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
  background: color-mix(in srgb, var(--color-background-elevation-raised) 92%, transparent);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-100);
  cursor: pointer;
  opacity: 0;
  transition: opacity 0.15s;
  display: inline-flex;
  position: absolute;
}
.bcn-phome__edit--cover {
  top: var(--spacing-300);
  right: var(--spacing-600);
}
.bcn-phome__cover:hover .bcn-phome__edit--cover,
.bcn-phome__edit--cover:focus-visible {
  opacity: 1;
}
.bcn-phome__sealwrap {
  flex-shrink: 0;
  position: relative;
}
.bcn-phome__edit--logo {
  padding: var(--spacing-150);
  border-radius: var(--radius-full);
  bottom: 0;
  right: 0;
}
.bcn-phome__sealwrap:hover .bcn-phome__edit--logo,
.bcn-phome__edit--logo:focus-visible {
  opacity: 1;
}
.bcn-phome__seal {
  border-radius: var(--radius-full);
  background: var(--color-background-elevation-raised);
  border: 3px solid var(--color-background-elevation-raised);
  object-fit: contain;
  width: 92px;
  height: 92px;
  box-shadow: var(--elevation-2, 0 2px 12px 0 #00000014);
  flex-shrink: 0;
  margin-top: -46px;
  display: block;
}
.bcn-phome__id {
  gap: var(--spacing-200);
  padding-top: var(--spacing-400);
  flex-direction: column;
  flex: 1;
  min-width: 0;
  display: flex;
}
.bcn-phome__idtop {
  align-items: center;
  gap: var(--spacing-300);
  flex-wrap: wrap;
  display: flex;
}
.bcn-phome__name {
  font-family: var(
    --font-decorative,
    var(--typography-font-family-display, var(--typography-font-family-sans))
  );
  font-weight: var(--typography-font-weight-bold);
  font-size: var(--font-size-600);
  line-height: var(--line-height-tight);
  letter-spacing: var(--letter-spacing-tight);
  color: var(--bcn-gray-1000, var(--color-content-default));
  margin: 0;
}
.bcn-phome__eyebrow {
  margin: 0 0 var(--spacing-200);
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-tertiary);
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon svg {
  width: var(--_icon-size);
  height: var(--_icon-size);
  display: block;
}
.breadcrumbs__items .esa-icon {
  color: var(--bcn-gray-400);
}
.page-layout__title h1 .esa-icon {
  color: var(--page-title-icon-color, var(--bcn-gray-1000));
  flex-shrink: 0;
}
.bcn-status-chip {
  align-items: center;
  gap: var(--spacing-150);
  padding: 2px var(--spacing-250);
  border-radius: var(--radius-full);
  font-size: var(--font-size-100);
  font-weight: var(--typography-font-weight-semibold);
  white-space: nowrap;
  background: color-mix(in srgb, var(--_chip) 16%, transparent);
  color: color-mix(in srgb, var(--_chip) 72%, #1a1a1a);
  display: inline-flex;
}
.bcn-status-chip__dot {
  border-radius: var(--radius-full);
  background: var(--_chip);
  flex-shrink: 0;
  width: 8px;
  height: 8px;
}

.bcn-tl {
  gap: var(--spacing-250);
  flex-direction: column;
  display: flex;
  position: relative;
}
.bcn-tl__row {
  align-items: center;
  gap: var(--spacing-300);
  grid-template-columns: 5.5rem 1fr;
  display: grid;
}
.bcn-tl__row--bars {
  align-items: start;
}
.bcn-tl__row--more {
  margin-top: calc(var(--spacing-250) * -1);
}
.bcn-tl__lane-label {
  font-size: 0.8125rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default-secondary);
}
.bcn-tl__track {
  height: 30px;
  position: relative;
}
.bcn-tl__row--axis .bcn-tl__track {
  height: 20px;
}
.bcn-tl__track--bars {
  height: 22px;
}
.bcn-tl__rule {
  background: var(--color-border-default);
  height: 1px;
  position: absolute;
  top: 50%;
  left: 0;
  right: 0;
}
.bcn-tl__today {
  background: var(--color-orange-400, #f9a134);
  z-index: 1;
  pointer-events: none;
  width: 2px;
  position: absolute;
  top: 0;
  bottom: -170px;
}
.bcn-tl__today-flag {
  font-size: 0.75rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-orange-400, #f9a134);
  position: absolute;
  top: -2px;
  left: 4px;
}
.bcn-tl__showall {
  font-family: inherit;
  font-size: 0.8125rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-background-brand);
  cursor: pointer;
  background: 0 0;
  border: 0;
  justify-self: start;
  padding: 0;
}
.bcn-tl__showall:hover {
  color: var(--color-background-brand-hover);
}
.bcn-tl__empty {
  font-size: var(--font-size-150);
  color: var(--color-content-default-tertiary);
  margin: 0;
}
.bcn-tl .bcn-tl__tick {
  color: var(--bcn-content-muted);
  white-space: nowrap;
  font-size: 0.75rem;
  position: absolute;
  top: 2px;
  transform: translate(-50%);
}
.bcn-tl .bcn-tl__item {
  cursor: pointer;
  border-radius: var(--radius-full);
  background: 0 0;
  border: 0;
  place-items: center;
  width: 30px;
  height: 30px;
  padding: 0;
  display: grid;
  position: absolute;
  top: 50%;
  transform: translate(-50%, -50%);
}
.bcn-tl .bcn-tl__item:hover,
.bcn-tl .bcn-tl__item[data-pinned] {
  background: color-mix(in srgb, var(--color-background-brand) 10%, transparent);
}
.bcn-tl .bcn-tl__item:focus-visible {
  outline: 2px solid var(--color-background-brand);
  outline-offset: -2px;
}
.bcn-tl .bcn-tl__dot {
  border-radius: var(--radius-full);
  background: var(--color-border-default-strong);
  border: 2px solid var(--color-background-elevation-raised);
  width: 11px;
  height: 11px;
  box-shadow: 0 0 0 1px var(--color-border-default);
  display: block;
}
.bcn-tl [data-urgency="overdue"] .bcn-tl__dot {
  background: var(--color-background-utility-danger);
  box-shadow: none;
}
.bcn-tl [data-urgency="due-soon"] .bcn-tl__dot {
  background: var(--color-background-utility-warning);
  box-shadow: none;
}
.bcn-tl .bcn-tl__diamond {
  background: var(--color-background-utility-info);
  width: 11px;
  height: 11px;
  display: block;
  transform: rotate(45deg);
}
.bcn-tl .bcn-tl__bar {
  align-items: center;
  gap: var(--spacing-200);
  height: 18px;
  padding: 0 var(--spacing-150);
  background: color-mix(
    in srgb,
    var(--color-background-brand-muted) 16%,
    var(--color-background-elevation-raised)
  );
  border: 1px solid
    color-mix(
      in srgb,
      var(--color-background-brand-muted) 40%,
      var(--color-background-elevation-raised)
    );
  border-radius: var(--radius-100);
  cursor: pointer;
  text-align: left;
  display: flex;
  position: absolute;
  overflow: hidden;
}
.bcn-tl .bcn-tl__bar:hover,
.bcn-tl .bcn-tl__bar[data-pinned] {
  background: color-mix(
    in srgb,
    var(--color-background-brand-muted) 26%,
    var(--color-background-elevation-raised)
  );
}
.bcn-tl .bcn-tl__bar-label {
  font-size: 0.75rem;
  font-weight: var(--typography-font-weight-semibold);
  color: var(--bcn-teal-800, var(--color-background-brand-muted-hover));
  white-space: nowrap;
  text-overflow: ellipsis;
  overflow: hidden;
}
.bcn-tl .bcn-tl__bar-dates {
  color: var(--color-content-default-tertiary);
  white-space: nowrap;
  margin-left: auto;
  font-size: 0.75rem;
}
@media (width<=720px) {
  .bcn-tl__row {
    grid-template-columns: 4rem 1fr;
  }
}

.typography-display-sm {
  font-family: var(--typography-display-sm-font-family);
  font-size: var(--typography-display-sm-font-size);
  font-weight: var(--typography-display-sm-font-weight);
  line-height: var(--typography-display-sm-line-height);
  letter-spacing: var(--typography-display-sm-letter-spacing);
}
.typography-label-md {
  font-family: var(--typography-label-md-font-family);
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-label-md-font-weight);
  line-height: var(--typography-label-md-line-height);
  letter-spacing: var(--typography-label-md-letter-spacing);
}
.bcn-search-trigger .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-cbadge {
  font-family: var(--typography-font-family-mono);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-commitment);
  background: color-mix(in srgb, var(--color-commitment) 12%, white);
  border-radius: var(--radius-100);
  white-space: nowrap;
  flex-shrink: 0;
  display: inline-block;
}
.bcn-cbadge--sm {
  padding: 1px var(--spacing-150);
  font-size: 0.75rem;
}
.bcn-admin-btn .esa-icon {
  block-size: 14px;
  inline-size: 14px;
}
.bcn-gd__label .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-gd-row .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-disclosure .esa-icon {
  transition: transform 0.15s;
}
.bcn-disclosure[aria-expanded="false"] .esa-icon {
  transform: rotate(-90deg);
}
@media (prefers-reduced-motion: reduce) {
  .bcn-disclosure .esa-icon {
    transition: none;
  }
}
.bcn-ev-staging__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.bcn-ev-targets__title .esa-icon {
  color: var(--color-content-default-tertiary);
  flex: none;
}
.user-panel__item .esa-icon {
  color: var(--bcn-gray-500);
}
.user-panel__item--danger .esa-icon {
  color: var(--color-background-utility-danger);
}
.project-switcher__trigger > .esa-icon:first-child {
  color: var(--bcn-gray-500);
  flex-shrink: 0;
}
.nav-section__header:hover .esa-icon,
.nav-section--active .nav-section__header,
.nav-section--active .nav-section__header .esa-icon {
  color: var(--color-background-brand);
}
.nav-section__header > .esa-icon:first-child {
  color: var(--bcn-gray-950);
  flex-shrink: 0;
  transition: color 0.15s;
}
.nav-section__header > .esa-icon:last-child {
  color: var(--bcn-gray-400);
  flex-shrink: 0;
  transition:
    transform 0.15s,
    opacity 0.2s ease-in-out;
}
.nav-section--collapsed .nav-section__header > .esa-icon:last-child {
  transform: rotate(-90deg);
}
.side-nav.collapsed .nav-section__title,
.side-nav.collapsed .nav-section__header > .esa-icon:last-child {
  display: none;
}
.bcn-tl__pop .bcn-cbadge {
  font-family: var(--typography-font-family-mono);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-commitment);
  background: color-mix(in srgb, var(--color-commitment) 12%, white);
  border-radius: var(--radius-100);
  padding: 1px var(--spacing-150);
  font-size: 0.75rem;
  display: inline-block;
}
.bcn-mod__grid {
  gap: var(--spacing-400);
  grid-template-columns: repeat(3, minmax(0, 1fr));
  display: grid;
}
@media (width<=900px) {
  .bcn-mod__grid {
    grid-template-columns: 1fr;
  }
}
.bcn-mod__card {
  gap: var(--spacing-300);
  padding: var(--spacing-400);
  background: var(--color-background-elevation-raised);
  border: 1px solid var(--color-border-default);
  border-radius: var(--radius-300);
  flex-direction: column;
  transition:
    border-color 0.15s,
    box-shadow 0.15s;
  display: flex;
  position: relative;
}
.bcn-mod__card:hover {
  border-color: var(--color-border-default-strong);
  box-shadow: var(--elevation-1, 0 1px 4px 0 #0000000d);
}
.bcn-mod__portal {
  border-radius: var(--radius-300);
  position: absolute;
  inset: 0;
}
.bcn-mod__portal:focus-visible {
  outline: 2px solid var(--color-background-brand);
  outline-offset: -2px;
}
.bcn-mod__head {
  align-items: center;
  gap: var(--spacing-300);
  display: flex;
}
.bcn-mod__glyph {
  border-radius: var(--radius-200);
  background: var(--color-background-elevation-sunken);
  width: 34px;
  height: 34px;
  color: var(--color-content-default-secondary);
  flex-shrink: 0;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.bcn-mod__name {
  font-size: var(--font-size-300);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-content-default);
}
.bcn-mod__rollup {
  gap: var(--spacing-300) var(--spacing-500);
  padding-bottom: var(--spacing-300);
  border-bottom: 1px solid var(--color-border-default-subtle);
  --stat-value-size: var(--font-size-400);
  --stat-label-size: var(--font-size-150);
  --stat-label-color: var(--color-content-default-tertiary);
  flex-wrap: wrap;
  display: flex;
}
.bcn-mod__actions {
  z-index: 1;
  gap: var(--spacing-200);
  flex-direction: column;
  margin: 0;
  padding: 0;
  list-style: none;
  display: flex;
  position: relative;
}
.bcn-mod__action {
  align-items: flex-start;
  gap: var(--spacing-200);
  color: inherit;
  text-decoration: none;
  display: flex;
}
.bcn-mod__dot {
  border-radius: var(--radius-full);
  background: var(--color-border-default-strong);
  flex-shrink: 0;
  width: 9px;
  height: 9px;
  margin-top: 5px;
}
[data-urgency="overdue"] .bcn-mod__dot {
  background: var(--color-background-utility-danger);
}
[data-urgency="due-soon"] .bcn-mod__dot {
  background: var(--color-background-utility-warning);
}
.bcn-mod__action-body {
  flex-direction: column;
  gap: 1px;
  min-width: 0;
  display: flex;
}
.bcn-mod__action-name {
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default);
  line-height: var(--line-height-tight);
}
.bcn-mod__action:hover .bcn-mod__action-name {
  color: var(--color-background-brand);
}
.bcn-mod__action-name .bcn-cbadge {
  margin-right: var(--spacing-150);
}
.bcn-mod__action-meta {
  color: var(--color-content-default-tertiary);
  text-overflow: ellipsis;
  white-space: nowrap;
  font-size: 0.8125rem;
  overflow: hidden;
}
.bcn-mod__more {
  z-index: 1;
  font-size: 0.8125rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
  text-decoration: none;
  position: relative;
}
.bcn-mod__more:hover {
  color: var(--color-background-brand);
}
.bcn-mod__links {
  z-index: 1;
  gap: var(--spacing-100);
  padding-top: var(--spacing-300);
  border-top: 1px solid var(--color-border-default-subtle);
  flex-direction: column;
  display: flex;
  position: relative;
}
.bcn-mod__link {
  align-items: center;
  gap: var(--spacing-100);
  font-size: 0.8125rem;
  font-weight: var(--typography-font-weight-medium);
  color: var(--color-content-default-secondary);
  align-self: flex-start;
  text-decoration: none;
  display: inline-flex;
}
.bcn-mod__link:hover {
  color: var(--color-background-brand);
}
.bcn-mod__link .esa-icon {
  color: var(--bcn-content-muted);
}
.bcn-mod__open {
  align-items: center;
  gap: var(--spacing-100);
  padding-top: var(--spacing-200);
  font-size: var(--font-size-150);
  font-weight: var(--typography-font-weight-semibold);
  color: var(--color-background-brand);
  margin-top: auto;
  display: inline-flex;
}
.bcn-mod__card:hover .bcn-mod__open {
  color: var(--color-background-brand-hover);
}
.typography-display-sm {
  font-family: var(--typography-display-sm-font-family);
  font-size: var(--typography-display-sm-font-size);
  font-weight: var(--typography-display-sm-font-weight);
  line-height: var(--typography-display-sm-line-height);
  letter-spacing: var(--typography-display-sm-letter-spacing);
}
.typography-label-md {
  font-family: var(--typography-label-md-font-family);
  font-size: var(--typography-label-md-font-size);
  font-weight: var(--typography-label-md-font-weight);
  line-height: var(--typography-label-md-line-height);
  letter-spacing: var(--typography-label-md-letter-spacing);
}
.esa-icon {
  --_icon-size: var(--icon-size-md, 20px);
  width: var(--_icon-size);
  height: var(--_icon-size);
  color: inherit;
  justify-content: center;
  align-items: center;
  display: inline-flex;
}
.esa-icon--sm {
  --_icon-size: var(--icon-size-sm, 16px);
}
.esa-icon--md {
  --_icon-size: var(--icon-size-md, 20px);
}
.esa-icon svg {
  width: var(--_icon-size);
  height: var(--_icon-size);
  display: block;
}
.esa-stat {
  --_stat-value-color: var(--stat-value-color, var(--color-content-default, #202020));
  --_stat-value-font: var(
    --typography-font-family-display,
    var(
      --typography-display-sm-font-family,
      var(--typography-font-family-display, "DM Sans", sans-serif)
    )
  );
  --_stat-value-size: var(
    --stat-value-size,
    var(--typography-display-sm-font-size, var(--font-size-700, 2.25rem))
